fn bitwise_and(x1: &Vec<u8>, x2: &Vec<u8>) -> Vec<u8> {
    assert_eq!(x1.len(), x2.len(), "inputs must have the same length");

    let mut out = Vec::with_capacity(x1.len());
    for i in 0..x1.len() {
        let a = x1[i];
        let b = x2[i];
        let y = a & b;

        // Element equals the bitwise AND of corresponding inputs.
        debug_assert_eq!(y, a & b);

        // Commutativity on these elements.
        debug_assert_eq!(a & b, b & a);

        // AND with zero yields zero.
        debug_assert_eq!(a & 0u8, 0u8);
        debug_assert_eq!(0u8 & b, 0u8);

        // AND with itself yields the original value.
        debug_assert_eq!(a & a, a);
        debug_assert_eq!(b & b, b);

        // Result is <= each corresponding input element.
        debug_assert!(y <= a);
        debug_assert!(y <= b);

        out.push(y);
    }
    out
}